import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Form,
  LookupSelect,
  RefName,
  Tiles,
  TextInput,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr03302Page({ role, notify }: PageProps) {
  const [created, setCreated] = useState<Row[]>([]);
  const [open, setOpen] = useState(false);
  const [resourceId, setResourceId] = useState<number | string>('');
  const [title, setTitle] = useState('');
  const [startDate, setStartDate] = useState('');
  const [startTime, setStartTime] = useState('09:00');
  const [endDate, setEndDate] = useState('');
  const [endTime, setEndTime] = useState('10:00');
  const [repeatRule, setRepeatRule] = useState('');
  const [reserverId, setReserverId] = useState<number | string>('');
  const [userId, setUserId] = useState<number | string>('');

  const pendingCount = created.filter((r) => r['approvalStatus'] === '신청').length;
  const approvedCount = created.filter((r) => r['approvalStatus'] === '승인').length;

  function reset() {
    setResourceId('');
    setTitle('');
    setStartDate('');
    setStartTime('09:00');
    setEndDate('');
    setEndTime('10:00');
    setRepeatRule('');
    setReserverId('');
    setUserId('');
  }

  async function submit() {
    if (resourceId === '' || !title.trim() || !startDate || !endDate || !startTime || !endTime || reserverId === '') {
      throw new Error('자원, 예약 내용, 시작·종료 일시, 예약자는 꼭 입력해 주세요.');
    }
    const startAt = startDate + 'T' + startTime + ':00';
    const endAt = endDate + 'T' + endTime + ':00';
    const result = await call('POST', '/resource-reservations', role, {
      resourceId,
      title,
      startAt,
      endAt,
      repeatRule: repeatRule || undefined,
      reserverId,
      userId: userId === '' ? undefined : userId,
    });
    setCreated([{ ...result, resourceId, title, startAt, endAt }, ...created]);
    setOpen(false);
    reset();
    notify('자원 예약을 등록했습니다.');
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>이번 등록</h2>
        <Tiles items={[['등록 건수', created.length]]} />
      </section>
      <section className="box span-4">
        <h2>승인 대기</h2>
        <Tiles items={[['신청 상태', pendingCount]]} />
      </section>
      <section className="box span-4">
        <h2>자동 승인</h2>
        <Tiles items={[['승인 상태', approvedCount]]} />
      </section>
      <section className="box span-12">
        <h2>예약 등록 내역</h2>
        <Band total={created.length}>
          <button type="button" onClick={() => setOpen(true)}>예약 등록</button>
        </Band>
        <DataTable
          rows={created}
          empty="이 화면에서 등록한 예약이 없습니다."
          columns={[
            { key: 'resourceReservationId', label: '자원 예약 ID' },
            {
              key: 'resourceId',
              label: '자원',
              render: (row) => <RefName table="resource" role={role} value={row['resourceId']} />,
            },
            { key: 'title', label: '예약 내용' },
            {
              key: 'startAt',
              label: '시작 일시',
              render: (row) => <DateText value={row['startAt']} time />,
            },
            {
              key: 'endAt',
              label: '종료 일시',
              render: (row) => <DateText value={row['endAt']} time />,
            },
            {
              key: 'approvalStatus',
              label: '예약 승인 상태',
              render: (row) => <Badge value={row['approvalStatus']} />,
            },
          ]}
        />
      </section>
      {open && (
        <Drawer title="자원 예약 등록" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="등록">
            <Field label="자원" required>
              <LookupSelect table="resource" role={role} value={resourceId} onChange={setResourceId} />
            </Field>
            <Field label="예약 내용" required wide>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label="시작 일자" required>
              <DateInput value={startDate} onChange={setStartDate} />
            </Field>
            <Field label="시작 시각" required hint="HH:mm">
              <TextInput value={startTime} onChange={setStartTime} placeholder="09:00" />
            </Field>
            <Field label="종료 일자" required>
              <DateInput value={endDate} onChange={setEndDate} />
            </Field>
            <Field label="종료 시각" required hint="HH:mm">
              <TextInput value={endTime} onChange={setEndTime} placeholder="10:00" />
            </Field>
            <Field label="반복 설정" wide>
              <TextInput value={repeatRule} onChange={setRepeatRule} />
            </Field>
            <Field label="예약자" required>
              <LookupSelect table="employee" role={role} value={reserverId} onChange={setReserverId} />
            </Field>
            <Field label="사용자">
              <LookupSelect table="employee" role={role} value={userId} onChange={setUserId} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
